def build_g(f):
    G={}; seen=set()
    for j in range(37):
        for k in range(37):
            if (j,k) in seen: continue
            orb=[]; jj,kk=j,k
            while (jj,kk) not in seen:
                seen.add((jj,kk)); orb.append((jj,kk)); jj,kk=(2*jj)%37,(2*kk)%37
            d=len(orb)
            v0=value(f,orb[0][0],orb[0][1])
            if v0==0:
                for p in orb: G[p]=0
                continue
            w=cube_root(v0,d)
            cur=w
            for p in orb:
                G[p]=cur; cur=mul(cur,cur)
    coeffs={}
    for a in range(37):
        for b in range(37):
            s=0
            for (j,k),Gv in G.items():
                if Gv==0: continue
                s ^= mul(Gv,(1<<((-(a*j+b*k))%37)))
            coeffs[(a,b)]=s
    return coeffs,G

